CREATE TYPE public.app_role AS ENUM ('team');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE TABLE public.team_access (email text PRIMARY KEY);
GRANT ALL ON public.team_access TO service_role;
ALTER TABLE public.team_access ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK (char_length(display_name) <= 100));
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.setup_team_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN
INSERT INTO public.profiles(id) VALUES (NEW.id) ON CONFLICT DO NOTHING;
IF NEW.email_confirmed_at IS NOT NULL AND EXISTS (SELECT 1 FROM public.team_access WHERE email = lower(NEW.email)) THEN INSERT INTO public.user_roles(user_id, role) VALUES (NEW.id, 'team') ON CONFLICT DO NOTHING; END IF;
RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.setup_team_account() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER setup_team_account AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.setup_team_account();
CREATE TABLE public.consultations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), client_name text NOT NULL CHECK (char_length(client_name) BETWEEN 1 AND 100), phone text NOT NULL CHECK (char_length(phone) BETWEEN 5 AND 30), matter_type text NOT NULL DEFAULT '', issue text NOT NULL CHECK (char_length(issue) BETWEEN 20 AND 4000), summary text, generation_status text NOT NULL DEFAULT 'preparing' CHECK (generation_status IN ('preparing','ready','failed','cancelled')));
GRANT SELECT ON public.consultations TO authenticated;
GRANT ALL ON public.consultations TO service_role;
ALTER TABLE public.consultations ENABLE ROW LEVEL SECURITY;
CREATE POLICY team_read_consultations ON public.consultations FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'team'));
CREATE INDEX consultations_created_at_idx ON public.consultations(created_at DESC);